#!/bin/bash
# generated by claude code
# count lines of C++ code in the repository using cloc
# only git-tracked files are counted, i.e. no build directories

display_usage() {
    echo ""
    echo "Usage: "
    echo "countlines.sh"
    echo "prints a cloc summary of all C++ code then a per-directory breakdown"
    echo "can be run from anywhere inside the repository"
}

if [ "$1" == "-h" ] || [ "$1" == "--help" ]; then
    display_usage
    exit 0
fi

if ! command -v cloc > /dev/null; then
    echo "cloc not found - please install it (e.g. brew install cloc)"
    exit 1
fi

root=$(git rev-parse --show-toplevel) || exit 1
cd "$root" || exit 1

langs="C++,C/C++ Header,C"

# overall summary by language
cloc --vcs=git --include-lang="$langs" --quiet .

# breakdown by top level directory
echo ""
printf "%-14s %8s %8s %8s\n" "directory" "blank" "comment" "code"
for d in */ ; do
    d=${d%/}
    result=$(cloc --vcs=git --include-lang="$langs" --quiet --csv "$d" 2>/dev/null | awk -F, '$2=="SUM"{print $3, $4, $5}')
    if [ -n "$result" ]; then
        read -r blank comment code <<< "$result"
        printf "%-14s %8d %8d %8d\n" "$d" "$blank" "$comment" "$code"
    fi
done
